#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

/*
*******************************************************************************
*BLINKER
*******************************************************************************
*/
static void Blinker(void);

//Definición de variables
volatile uint8_t cambio = 0;    //Indicador de estado
uint8_t parpadeos = 0;

//Funciones 

void init_GPIO(void);
void init_EXTI(void);
void init_timer(void);

typedef enum{
    Rojo,
    VerdeE,
    Amarillo,
} EstadoSemaforo;

EstadoSemaforo estado_actual = Rojo; //

int main(void)
{
    Blinker();
    init_GPIO();
    init_EXTI();
    


    /* Loop forever */
	while (1) {
        if (cambio == 1) {
            cambio = 0;

            switch (estado_actual) {

                //Verde PB8, Amarillo PB9, Rojo PB6

                case Rojo:
                    GPIOB->ODR |= GPIO_ODR_OD6; // Encender LED rojo
                    GPIOB->ODR &= ~GPIO_ODR_OD8; // Apagar LED verde
                    GPIOB->ODR &= ~GPIO_ODR_OD9; // Apagar LED amarillo

                    estado_actual = VerdeE;
                    break;
                
                case VerdeE:
                    GPIOB->ODR |= GPIO_ODR_OD8; // Encender LED verde
                    GPIOB->ODR &= ~GPIO_ODR_OD9; // Apagar LED amarillo
                    GPIOB->ODR &= ~GPIO_ODR_OD6; // Apagar LED rojo

                    estado_actual = Amarillo;
                    break;

              

                case Amarillo:
                    GPIOB->ODR |= GPIO_ODR_OD9; // Encender LED amarillo
                    GPIOB->ODR &= ~GPIO_ODR_OD6; // Apagar LED rojo
                    GPIOB->ODR &= ~GPIO_ODR_OD8; // Apagar LED verde

                    estado_actual = Rojo;
                    break;

                default:
                    estado_actual = Rojo;
                    break;     
            
            }
        
        }

    }

    return 0;
}

void TIM1_UP_TIM10_IRQHandler(void){

if ((TIM10->SR & TIM_SR_UIF) != 0U) 
{
    TIM10->SR &= ~TIM_SR_UIF;    //limpiar la bandera de actualización
    GPIOH->ODR ^= (GPIO_ODR_OD1);//alternar el LED 
}

}


void Blinker(void){
 
    //iniciar PH1 (LED_BREADBOARD)
     RCC->AHB1ENR |= RCC_AHB1ENR_GPIOHEN;   //IO port H clock enabled
    GPIOH->MODER  &= ~GPIO_MODER_MODE1;     //LIMPIAR MODO
    GPIOH->MODER  |= GPIO_MODER_MODE1_0;    //01: General purpose output mode
    GPIOH->OTYPER &= ~GPIO_OTYPER_OT1;      //Output push-pull
    GPIOH->PUPDR  &= ~GPIO_PUPDR_PUPD1;     //No pull-up, pull-down      
    GPIOH->BSRR   &= ~GPIO_BSRR_BR1;        //No action on the corresponding ODRx bit
    //iniciar timer TIM10
    RCC->APB2ENR |= RCC_APB2ENR_TIM10EN;    //TIM10 clock enabled
    
    TIM10->DIER  |= TIM_DIER_UIE;           //Update interrupt enabled
    TIM10->CNT   &= ~TIM_CNT_CNT;           //CONTADOR EN CERO
    TIM10->PSC   = 16000-1;                  //16 MHz / 16000 = tick de 1 ms
    TIM10->ARR   = 500-1;                     //500 ticks -> evento cada 500 ms 
    TIM10->CR1   |= TIM_CR1_CEN;            //Counter enabled
    NVIC_EnableIRQ(TIM1_UP_TIM10_IRQn);//habilitar la línea de interrupción en el NVIC
}   

void init_GPIO(void){

    //Señal de reloj GPIOB (LEDs) y GPIOC (botón)

 

    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOBEN;
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN;

    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOCEN;
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN;

    
    //CONFIGURACIÓN PARA EL PUERTO B: PB6, PB8 & PB9

    GPIOB->MODER &= ~(GPIO_MODER_MODE6 | GPIO_MODER_MODE8 | GPIO_MODER_MODE9); //LIMPIAR MODO
    GPIOB->MODER |= (GPIO_MODER_MODE6_0 | GPIO_MODER_MODE8_0 | GPIO_MODER_MODE9_0); //General purpose output mode
    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT6 | GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);     //Output push-pull (reset state)
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDER_OSPEEDR6 | GPIO_OSPEEDER_OSPEEDR8 | GPIO_OSPEEDER_OSPEEDR9); //Low speed
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD6 | GPIO_PUPDR_PUPD8 | GPIO_PUPDR_PUPD9);  //No pull-up, pull-down
    GPIOB->ODR &= ~(GPIO_ODR_OD6 | GPIO_ODR_OD8 | GPIO_ODR_OD9);        //INICIAR APAGADO

    //fotointerruptor 
    GPIOB->MODER &= ~GPIO_MODER_MODE13;     //Input (reset state)
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD13;     //No pull-up, pull-down
}

void init_EXTI(void){

    RCC->APB2ENR &= ~RCC_APB2ENR_SYSCFGEN;  //System configuration controller clock disabled
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;   //System configuration controller clock enabled

    SYSCFG->EXTICR[3] &= ~SYSCFG_EXTICR4_EXTI13;    //IMPIAR
    SYSCFG->EXTICR[3] |= SYSCFG_EXTICR4_EXTI13_PB;  //PB[x] pin (La línea EXTI13 viene del puerto B)

    EXTI->RTSR |= EXTI_RTSR_TR13;  //Rising trigger enabled (FLANCO DE SUBIDA ACTIVADO)
    EXTI->FTSR &= ~EXTI_FTSR_TR13;   //Falling trigger disabled (FLANCO DE BAJADO DESACTIVADO)

    EXTI->PR |=  EXTI_PR_PR13;     //No trigger request occurred (LIMPIAR BANDERA)
    EXTI->IMR |= EXTI_IMR_MR13;     //Interrupt request from line x is not masked

    
    __NVIC_EnableIRQ(EXTI15_10_IRQn);   //Habilitar en el NVIC la interrupción de las líneas EXTI 10 a 15


}




void EXTI15_10_IRQHandler(void){
    if (EXTI->PR & EXTI_PR_PR13) {  //SI LA LINEA 13 GENERÓ LA INTERRUPCIÓN...
        EXTI->PR |= EXTI_PR_PR13;   //LIMPIAR BANDERA
        cambio = 1;                 //cambiar indicador de estado a 1 
    }
}

